package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class SubmissionReviewStoreIntegrationTest {
 SubmissionFeedbackStoreIntegrationTest f;SubmissionReviewStore store;FeedbackRetractionStore retractions;ResubmissionRequestStore requests;
 @BeforeEach void setup(){f=new SubmissionFeedbackStoreIntegrationTest();f.setup();store=new SubmissionReviewStore(f.f.f.source,f.f.parent.store);retractions=new FeedbackRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());requests=new ResubmissionRequestStore(f.f.f.source,f.f.parent.store,Clock.systemUTC());}
 SubmissionReviewStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,f.f.study,f.f.assignment,after,limit,filter);}
 SubmissionReviewStore.Review row(){return list("ALL",null,20).items().getFirst();}
 FeedbackRetractionStore.Retraction mark(long feedbackVersion,long expected,String state){return retractions.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,feedbackVersion,expected,new FeedbackRetractionInput(state,"Reason"),f.f.f.trace);}
 ResubmissionRequestStore.Request request(long expected,long submissionVersion){return requests.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,expected,new ResubmissionRequestInput("REQUEST","Please revise",submissionVersion,2),f.f.f.trace);}
 @Test void defaultSummaryIsOnlyBoundedMetadataWithNoImplicitCreation(){var v=row();assertEquals(f.answer.submissionId(),v.submissionId());assertEquals(f.f.author,v.authorId());assertTrue(v.needsFeedback());assertNull(v.feedbackVersion());assertNull(v.feedbackSubmissionVersion());assertEquals("NONE",v.retractionState());assertNull(v.requestVersion());assertEquals("NONE",v.requestState());assertNull(v.requestedSubmissionVersion());assertEquals(1,list("NEEDS_FEEDBACK",null,20).items().size());assertTrue(list("HAS_FEEDBACK",null,20).items().isEmpty());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(v);assertEquals(12,json.size());for(String key:List.of("content","reason","snapshot","title","description"))assertFalse(json.has(key));assertNull(f.get(f.f.author,false).feedback());}
 @Test void latestFeedbackAndOnlyItsRetractionDetermineNeedsWithoutGrading(){var first=f.change(0,1,"First opinion");assertFalse(row().needsFeedback());assertEquals(1L,row().feedbackVersion());assertEquals(1,list("HAS_FEEDBACK",null,20).items().size());mark(1,0,"RETRACTED");assertTrue(row().needsFeedback());assertEquals(1,list("RETRACTED_FEEDBACK",null,20).items().size());assertTrue(list("HAS_FEEDBACK",null,20).items().isEmpty());mark(1,1,"RESTORED");assertFalse(row().needsFeedback());assertTrue(list("RETRACTED_FEEDBACK",null,20).items().isEmpty());f.f.submit(f.f.f.key(),1,2,"New answer");assertEquals(2,row().version());assertEquals(1L,row().feedbackSubmissionVersion());assertTrue(row().needsFeedback());mark(1,2,"RETRACTED");f.change(1,2,"Explicit comment on new answer");assertEquals(2L,row().feedbackVersion());assertEquals("NONE",row().retractionState());assertFalse(row().needsFeedback());assertEquals("RETRACTED",retractions.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,1).retraction().state());assertEquals(first,f.history(2,5).items().getFirst().snapshot());}
 @Test void pendingCancelledAndResolvedRequestsRemainIndependentOfFeedback(){var requested=request(0,1);assertTrue(row().needsFeedback());assertEquals("REQUESTED",row().requestState());assertEquals(1L,row().requestVersion());assertEquals(1L,row().requestedSubmissionVersion());assertEquals(1,list("PENDING_RESUBMISSION",null,20).items().size());f.change(0,1,"Opinion while pending");assertFalse(row().needsFeedback());assertEquals(1,list("PENDING_RESUBMISSION",null,20).items().size());requests.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,requested.version(),new ResubmissionRequestInput("CANCEL",null,0,0),f.f.f.trace);assertTrue(list("PENDING_RESUBMISSION",null,20).items().isEmpty());assertEquals("CANCELLED",row().requestState());request(2,1);f.f.submit(f.f.f.key(),1,2,"Requested new answer");assertEquals("RESOLVED",row().requestState());assertEquals(4L,row().requestVersion());assertEquals(1L,row().requestedSubmissionVersion());assertTrue(row().needsFeedback());assertTrue(list("PENDING_RESUBMISSION",null,20).items().isEmpty());}
 @Test void keysetPaginationIsStableAndFiltersApplyBeforeLimit(){for(int n=0;n<2;n++)f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.ids.next(),0,2,f.f.f.key(),"Other private answer "+n,f.f.f.trace);var first=list("ALL",null,1);assertEquals(1,first.items().size());assertNotNull(first.nextAfter());var second=list("ALL",first.nextAfter(),1);var third=list("ALL",second.nextAfter(),1);assertNull(third.nextAfter());assertEquals(3,Set.of(first.items().getFirst().submissionId(),second.items().getFirst().submissionId(),third.items().getFirst().submissionId()).size());f.change(0,1,"Only one current opinion");assertEquals(1,list("HAS_FEEDBACK",null,1).items().size());assertNull(list("HAS_FEEDBACK",null,1).nextAfter());assertEquals(2,list("NEEDS_FEEDBACK",null,20).items().size());for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));f.status(400,()->list("all",null,20));}
 @Test void exactGroupSpaceStudyAssignmentScopeIsRequired(){f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,f.f.study,f.f.assignment,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),f.f.study,f.f.assignment,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.space,f.f.f.ids.next(),f.f.assignment,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.space,f.f.study,f.f.f.ids.next(),null,20,"ALL"));var other=f.f.parent.create(f.f.f.key()).assignment().assignmentId();assertTrue(store.list(f.f.group,f.f.space,f.f.study,other,null,20,"ALL").items().isEmpty());}
 @Test void closedArchivedReadsDoNotMutateAnyAggregateOrAudit(){var feedback=f.change(0,1,"Opinion");var marker=mark(1,0,"RETRACTED");var pending=request(0,1);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int events=f.f.events(feedback.feedbackId())+f.f.events(marker.retractionId())+f.f.events(pending.requestId())+f.f.events(f.answer.submissionId());for(var filter:SubmissionReviewStore.FILTERS)list(filter,null,20);assertTrue(row().needsFeedback());assertEquals("REQUESTED",row().requestState());assertEquals(feedback,f.get(f.f.author,false).feedback());assertEquals(f.answer,f.f.store.mine(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.author,true).submission());assertEquals(events,f.f.events(feedback.feedbackId())+f.f.events(marker.retractionId())+f.f.events(pending.requestId())+f.f.events(f.answer.submissionId()));}
 @Test void requestResolutionAndNewAnswerAreReadFromOneStatementSnapshot()throws Exception{request(0,1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reads=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();if(v.requestState().equals("REQUESTED"))assertEquals(v.version(),v.requestedSubmissionVersion());else{assertEquals("RESOLVED",v.requestState());assertTrue(v.requestedSubmissionVersion()<v.version());}}return true;});var submit=pool.submit(()->{barrier.await();return f.f.submit(f.f.f.key(),1,2,"Concurrent new answer");});assertTrue(reads.get(20,TimeUnit.SECONDS));assertEquals(2,submit.get(20,TimeUnit.SECONDS).submission().version());assertEquals("RESOLVED",row().requestState());}}
}
